import{_ as t,a as o,c as r,ac as a}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"Go语言高并发与微服务实战","description":"按2020年版13章整理 Go、微服务组件与秒杀系统实战的阅读导引。","frontmatter":{"title":"Go语言高并发与微服务实战","description":"按2020年版13章整理 Go、微服务组件与秒杀系统实战的阅读导引。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"书籍导读","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"书单 · 计算机与软件工程 · 编程语言与开发框架","summary":"按2020年版13章整理 Go、微服务组件与秒杀系统实战的阅读导引。","status":"active","related":[{"title":"C语言程序设计","link":"/life/personal/books/computing/c-programming","kind":"书籍导读","scope":"general","audience":"general"},{"title":"深入浅出Spring Boot 2.x","link":"/life/personal/books/computing/spring-boot-2","kind":"书籍导读","scope":"general","audience":"general"},{"title":"Redis设计与实现","link":"/life/personal/books/computing/redis-design","kind":"书籍导读","scope":"general","audience":"general"},{"title":"Rust程序设计（第2版）","link":"/life/personal/books/computing/programming-rust","kind":"书籍导读","scope":"general","audience":"general"}],"prev":{"text":"C语言程序设计","link":"/life/personal/books/computing/c-programming"},"next":{"text":"深入浅出Spring Boot 2.x","link":"/life/personal/books/computing/spring-boot-2"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"C语言程序设计","link":"/life/personal/books/computing/c-programming"},"next":{"text":"深入浅出Spring Boot 2.x","link":"/life/personal/books/computing/spring-boot-2"}},"headers":[],"relativePath":"life/personal/books/computing/go-concurrency-microservices.md","filePath":"life/personal/books/computing/go-concurrency-microservices.md"}'),n={name:"life/personal/books/computing/go-concurrency-microservices.md"};function i(l,e,d,s,p,c){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="go语言高并发与微服务实战" tabindex="-1">Go语言高并发与微服务实战 <a class="header-anchor" href="#go语言高并发与微服务实战" aria-label="Permalink to &quot;Go语言高并发与微服务实战&quot;">​</a></h1><p><a href="./../overview">返回分类书单</a></p><p><strong>分类：计算机与软件工程 / 编程语言与开发框架</strong></p><h2 id="书籍简介" tabindex="-1">书籍简介 <a class="header-anchor" href="#书籍简介" aria-label="Permalink to &quot;书籍简介&quot;">​</a></h2><p>这本书的阅读方向连接 Go 并发编程与服务开发：先理解 goroutine、通信和同步，再思考超时、取消、依赖故障和资源限制如何影响一个服务。适合具备基本 Go 语法、准备编写后端服务的读者。</p><p>学习目标不应停留在“启动很多 goroutine”，而应能够回答它们何时结束、怎样传播错误、最多占用多少资源，以及请求失败后已经发生的操作如何处理。</p><h2 id="版本说明" tabindex="-1">版本说明 <a class="header-anchor" href="#版本说明" aria-label="Permalink to &quot;版本说明&quot;">​</a></h2><p>本页对应朱荣鑫、黄迪璇、张天著，中国铁道出版社 <strong>2020 年版</strong>，ISBN <strong>9787113266622</strong>。依据该 ISBN 的公开书目目录整理全部 13 章；尚未直接复核出版社完整目录。随书仓库 README 明确使用 Go 1.12.4；Go 与微服务框架持续演进，其他依赖版本仍需按仓库核对，不把当前工具链行为反向写成原书内容。</p><h2 id="作者与背景" tabindex="-1">作者与背景 <a class="header-anchor" href="#作者与背景" aria-label="Permalink to &quot;作者与背景&quot;">​</a></h2><p>作者为朱荣鑫、黄迪璇、张天。随书代码仓库由 longjoy 维护，公开了与服务发现、RPC、容错、链路追踪及秒杀案例对应的实现，README 明确基于 Go 1.12.4。可检查的代码与依赖是评价工程内容的依据；本页未取得三位作者完整的一手履历，不把书商介绍中的任职写成当前事实。</p><h2 id="目标读者" tabindex="-1">目标读者 <a class="header-anchor" href="#目标读者" aria-label="Permalink to &quot;目标读者&quot;">​</a></h2><p>适合掌握 Go 语法、能读 HTTP 服务代码、希望理解微服务组件如何连接的后端开发者。纯语法初学者应先写小服务；准备生产设计的人应补上容量规划、数据一致性和故障演练。</p><h2 id="章节介绍" tabindex="-1">章节介绍 <a class="header-anchor" href="#章节介绍" aria-label="Permalink to &quot;章节介绍&quot;">​</a></h2><table tabindex="0"><thead><tr><th>章节</th><th>阅读关注点</th></tr></thead><tbody><tr><td>第1章 云原生架构</td><td>从虚拟化、容器和编排的发展理解云原生的组成与目标。</td></tr><tr><td>第2章 微服务概述</td><td>比较架构演进与框架选择，认识拆分服务所带来的协作成本。</td></tr><tr><td>第3章 Go 语言基础</td><td>梳理语法、数据与程序组织，为后续服务开发建立基础。</td></tr><tr><td>第4章 进阶——Go 语言高级特性</td><td>学习语言的进一步能力，结合并发与同步思考资源和生命周期。</td></tr><tr><td>第5章 构建 Go Web 服务器</td><td>从请求处理进入服务端程序，明确输入、响应和错误路径。</td></tr><tr><td>第6章 服务注册与发现</td><td>讨论服务位置怎样发布和查询，以及实例变化如何传播。</td></tr><tr><td>第7章 远程过程调用 RPC</td><td>将本地接口扩展到网络调用，关注序列化、超时和失败语义。</td></tr><tr><td>第8章 分布式配置中心</td><td>分析配置管理、分发与更新，区分配置已发布和服务已生效。</td></tr><tr><td>第9章 微服务网关</td><td>理解入口路由与横切功能的集中处理，以及网关自身的可用性。</td></tr><tr><td>第10章 微服务的容错处理与负载均衡</td><td>讨论故障隔离和流量分配，检查重试、降级与过载之间的关系。</td></tr><tr><td>第11章 统一认证与授权</td><td>区分身份确认与权限判断，分析跨服务传递身份的边界。</td></tr><tr><td>第12章 分布式链路追踪</td><td>将一次请求的多个调用关联，定位延迟和失败传播的位置。</td></tr><tr><td>第13章 综合实战：秒杀系统的设计与实现</td><td>通过高并发业务整合服务组件，关注限流、库存与失败处理。</td></tr></tbody></table><h2 id="读后感" tabindex="-1">读后感 <a class="header-anchor" href="#读后感" aria-label="Permalink to &quot;读后感&quot;">​</a></h2><p>以下为本站阅读评析，用可实践的阅读目标表达收获，不代表书单提供者已经读完、任职或完成相应项目。版本未明时，评析只针对本页明确标注的主题或参考版本。</p><h3 id="金句摘抄或阅读提炼" tabindex="-1">金句摘抄或阅读提炼 <a class="header-anchor" href="#金句摘抄或阅读提炼" aria-label="Permalink to &quot;金句摘抄或阅读提炼&quot;">​</a></h3><blockquote><p>并发设计的第一问，是每个任务如何结束。</p></blockquote><p>这是本站原创阅读提炼，不是原书引文；没有可核对页码的原文不作逐字摘抄。</p><h3 id="个人收获" tabindex="-1">个人收获 <a class="header-anchor" href="#个人收获" aria-label="Permalink to &quot;个人收获&quot;">​</a></h3><p>可为一个服务调用画出超时、取消、排队和失败返回路径，逐项检查 goroutine 能否退出、重试是否增加负载、库存扣减是否可重复执行。阅读收益应落在可说明的资源上限和失败语义，而不只是组件安装清单。</p><h3 id="客观评价与阅读建议" tabindex="-1">客观评价与阅读建议 <a class="header-anchor" href="#客观评价与阅读建议" aria-label="Permalink to &quot;客观评价与阅读建议&quot;">​</a></h3><p>全链路案例有利于建立组件地图，但 Go 1.12.4 与成书时依赖具有明显时代边界。先按仓库版本读懂结构，再逐个升级依赖；不要把示例能启动当作并发安全或业务一致性已经被证明。</p><p><strong>推荐语（本站原创，非原书引用）：</strong> 推荐给正从 Go 小程序走向服务开发的人：用失败路径重读每一章，会比只复现正常流程更接近工程实践。</p><h2 id="来源与核对入口" tabindex="-1">来源与核对入口 <a class="header-anchor" href="#来源与核对入口" aria-label="Permalink to &quot;来源与核对入口&quot;">​</a></h2><ul><li><a href="https://book.douban.com/subject/35055766/" target="_blank" rel="noopener noreferrer">对应 ISBN 的中文书目与完整目录</a>：作者、2020 年版本与 13 章结构的核对来源。</li><li><a href="https://go.dev/doc/" target="_blank" rel="noopener noreferrer">Go 官方文档</a>：语言、工具与学习资源入口。</li><li><a href="https://go.dev/blog/pipelines" target="_blank" rel="noopener noreferrer">Go 并发模式：流水线与取消</a>：并发任务退出和取消的补充参考，不作为本书目录证据。</li><li><a href="https://github.com/longjoy/micro-go-book" target="_blank" rel="noopener noreferrer">随书代码与环境说明</a>：一手代码证据，明确 Go 1.12.4；可按目录定位案例。</li></ul>',26)])])}const u=t(n,[["render",i]]);export{g as __pageData,u as default};
